import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './Aiiot.css'; 

// Icon Replacement Component (Using SVG instead of Feather Icons)
const FeatherIcon = ({ name, className = "" }) => {
    const iconMap = {
        'trending-up': (
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
                <polyline points="23 6 13.5 15.5 8.5 10.5 1 18"></polyline>
                <polyline points="17 6 23 6 23 12"></polyline>
            </svg>
        ),
        'settings': (
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
                <circle cx="12" cy="12" r="3"></circle>
                <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"></path>
            </svg>
        )
    };
    return iconMap[name] || null;
};

// Carousel Images (Base64 placeholders to ensure rendering)
const CAROUSEL_IMAGES = [
    { src: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=", alt: "AI-IoT Innovation Technology" },
    { src: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=", alt: "Research Laboratory" },
    { src: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=", alt: "Collaborative Technology" }
];

// Project Data
const PROJECT_DATA = [
    { 
        title: "AI Hardware Design", 
        description: "Advanced neural network hardware integration",
        link: "#",
        icon: "trending-up"
    },
    { 
        title: "IoT Connectivity", 
        description: "Next-generation sensor network protocols",
        link: "#", 
        icon: "settings"
    }
];

// Rest of the code remains the same as the original file...
// (HeroSection, AboutSection, AiIotInnovationCenter components are unchanged)

export const HeroSection = () => {
    const [currentImageIndex, setCurrentImageIndex] = useState(0);

    useEffect(() => {
        const interval = setInterval(() => {
            setCurrentImageIndex((prevIndex) => 
                (prevIndex + 1) % CAROUSEL_IMAGES.length
            );
        }, 4000);

        return () => clearInterval(interval);
    }, []);

    return (
        <section id="hero" className="relative hero-gradient py-20 md:py-32">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
                <h1 className="text-4xl md:text-6xl font-extrabold text-slate-800 mb-4 leading-tight reveal-on-scroll">
                    <span className="block text-2xl md:text-4xl font-medium text-slate-600">Sponsored by</span>
                    <span className="text-blue-600">Ministry of Electronics and Information Technology</span>
                </h1>
                <p className="text-lg md:text-xl text-slate-600 mb-10 max-w-3xl mx-auto reveal-on-scroll">
                    The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design with artificial intelligence (AI) and explainable AI (XAI).
                </p>
                <div className="flex flex-col sm:flex-row justify-center items-center gap-4 mb-12 reveal-on-scroll">
                    <Link 
                        to="/projects" 
                        className="w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-lg shadow-lg transition duration-300 transform hover:scale-105"
                    >
                        Explore Projects
                    </Link>
                    <Link 
                        to="/about" 
                        className="w-full sm:w-auto bg-white hover:bg-slate-100 text-slate-800 font-bold py-3 px-8 rounded-lg border border-slate-300 shadow-md transition duration-300 transform hover:scale-105"
                    >
                        Learn More
                    </Link>
                </div>

                {/* Hero Image Carousel */}
                <div className="relative max-w-5xl mx-auto reveal-on-scroll">
                    <div className="absolute -inset-2 bg-gradient-to-r from-blue-400 to-indigo-500 rounded-2xl blur-lg opacity-25"></div>
                    <div className="relative w-full h-auto overflow-hidden rounded-xl shadow-2xl">
                        <img 
                            src={CAROUSEL_IMAGES[currentImageIndex].src} 
                            alt={CAROUSEL_IMAGES[currentImageIndex].alt} 
                            className="w-full h-auto object-cover transition-all duration-1000 ease-in-out"
                        />
                    </div>
                    <div className="flex justify-center mt-6 space-x-3">
                        {CAROUSEL_IMAGES.map((_, index) => (
                            <div 
                                key={index} 
                                className={`w-3 h-3 rounded-full cursor-pointer ${
                                    index === currentImageIndex 
                                    ? 'bg-blue-600' 
                                    : 'bg-blue-300'
                                }`}
                                onClick={() => setCurrentImageIndex(index)}
                            ></div>
                        ))}
                    </div>
                </div>
            </div>
        </section>
    );
};

export const AboutSection = () => {
    return (
        <section id="about" className="py-20 bg-white">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="text-center mb-12 reveal-on-scroll">
                    <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">About Our Center</h2>
                    <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">
                        Pioneering research where intelligence meets connectivity.
                    </p>
                </div>
                <div className="grid md:grid-cols-2 gap-12 items-center">
                    <div className="reveal-on-scroll">
                        <div className="rounded-xl overflow-hidden shadow-lg border border-slate-200">
                            <img 
                                src={CAROUSEL_IMAGES[0].src} 
                                alt="Collaborative team working in a modern tech lab" 
                                loading="lazy" 
                                className="w-full h-auto object-cover"
                            />
                        </div>
                    </div>
                    <div className="reveal-on-scroll">
                        <h3 className="text-2xl font-bold text-slate-800 mb-4">
                            Our Mission
                        </h3>
                        <p className="text-slate-600 mb-4">
                            We bridge the gap between advanced electronics, artificial intelligence, and internet of things technologies to create innovative solutions that transform industries.
                        </p>
                        <div className="space-y-3">
                            {PROJECT_DATA.map((project, index) => (
                                <div key={index} className="flex items-start space-x-3">
                                    <FeatherIcon name={project.icon} className="text-blue-600 w-5 h-5" />
                                    <div>
                                        <h4 className="font-semibold text-slate-800">{project.title}</h4>
                                        <p className="text-slate-600 text-sm">{project.description}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
};

